for(const [en,es] of Object.entries(translations)){if(!englishBySpanish.has(es))englishBySpanish.set(es,en)}
Object.assign(translations,{"Owner review":"Revisión antes de entregar ·","Plan your work":"Planifica el trabajo","Choose a purchased client. Dates are your own production targets, not automatic promises to the buyer.":"Son fechas de trabajo internas, no promesas de entrega.","Design & pricing":"Diseño y precios","Private work notes":"Notas de trabajo","Save work dates":"Guardar fechas","Production: an estimated 48 hours starting during business hours after payment, completed intake, required access and approvals. Saturday after 12 PM ET begins Monday or the next business day.":"Producción: 48 horas estimadas desde el inicio en horario laborable, después del pago, intake, accesos y aprobaciones. Sábado después de las 12 PM (Este): comienza el lunes o siguiente día hábil.","One guided setup for each purchased Booking Page + private Command Center.":"Configura cada sistema sin duplicar los demos.","1. Intake":"Datos de la compradora","Business name":"Nombre comercial","Hero headline":"Título principal","Business description":"Descripción","Service area":"Zona de servicio","Choose the logo and main photo from the files uploaded in the intake. No URLs needed.":"Elige el logo y la foto principal de las imágenes recibidas. No necesitas enlaces.","📷 Upload photos yourself":"Subir fotos tú misma","Photos from your phone or computer · JPG, PNG, WebP · up to 10 per buyer.":"Fotos del teléfono o computadora · hasta 10.","Hero photo":"Foto principal","No photo":"Sin foto","No logo":"Sin logo","Photos for detailing services":"Fotos para cada servicio","HEIC photos can be received and stored, but JPG, PNG or WebP is required for a website image.":"Puedes recibir fotos HEIC, pero para publicarlas necesitarás JPG, PNG o WebP.","Accent color":"Azul de acento","Received from the intake. Review the text and names before publishing.":"Revisa los textos y nombres antes de publicar.","Client name":"Nombre","Star rating":"Calificación","Save design":"Guardar diseño","This uses the same Booking Page template customers will receive, with no reservations, emails or charges.":"Utiliza el diseño real pero sin crear reservas.","Mobile":"Móvil","Approve the design":"Aprobar diseño","First save the design, set prices and open hours, then approve the preview. Preparing access does not publish bookings or send the final delivery email.":"No publica la página ni manda el correo final.","Verify privately — no email":"Verificar sin enviar correo","Open Activation Email":"Abrir activación","✉ Client Emails":"Correos del cliente","Private Command Center access · Prepared email for this customer. Nothing is sent until you confirm.":"Acceso privado: no se envía hasta tu confirmación.","To":"Para","From":"De","Business category":"Tipo de negocio","Preview only: the actual secure link is generated when you approve sending.":"El enlace seguro se genera al enviar.","Review & send access":"Revisar y enviar acceso","Confirm buyer sign-in, lead routing, services, availability, follow-ups, notifications and account privacy. Then approve the six delivery checks in Settings.":"Prueba todo y aprueba la entrega.","Open final QA & delivery":"Revisar y entregar","Private owner checklist. Nothing is sent until the complete personalized system is ready, all six checks are confirmed, and you approve the final delivery.":"Nada se envía hasta que el sistema esté preparado y apruebes las seis pruebas.","Review":"Revisar","A successful sample test is separate from your design approval.":"La prueba técnica es independiente de tu aprobación.","What would you like us to fix?":"¿Qué debemos corregir?","Submitting this request uses one included revision. Technical problems are fixed separately.":"Enviar consume una revisión incluida. Las fallas técnicas se atienden aparte.","Sending details":"Detalles de envío","Campaign readiness":"Estado de las campañas","Contactar? (your manual decision)":"¿Contactar?","Yes":"Sí, contactar","This records the owner's decision only. Historical import notes do not override a newer Yes decision, but confirmed opt-outs, bounces and email permission still apply.":"Es tu decisión; no equivale a permiso del destinatario para recibir correos."});
